import React, { useState } from 'react';
import API from '../api/axiosClient';
import { useNavigate } from 'react-router-dom';
import { FaUserPlus, FaEnvelope, FaLock, FaUser } from 'react-icons/fa';

export default function Register({ orgId }) {
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [role, setRole] = useState('customer');
    const [error, setError] = useState('');
    const navigate = useNavigate();

    const handleRegister = async (e) => {
        e.preventDefault();
        setError('');

        try {
            await API.post(`/auth/${orgId}/register`, { name, email, password, role });
            navigate('/login');
        } catch (err) {
            setError(err.response?.data?.error || 'Registration failed');
        }
    };

    return (
        <div className="min-h-screen bg-gray-900 text-white flex items-center justify-center p-6">
            <div className="max-w-md w-full bg-gray-800 p-8 rounded-xl border border-gray-700 shadow-xl">
                <h2 className="text-2xl font-bold mb-6 text-center flex items-center justify-center gap-2">
                    <FaUserPlus className="text-emerald-400" /> Create Account
                </h2>

                {error && (
                    <div className="mb-4 p-3 bg-red-900 border border-red-700 rounded-lg text-sm text-red-200">
                        {error}
                    </div>
                )}

                <form onSubmit={handleRegister} className="space-y-4">
                    <div>
                        <label className="block text-sm text-gray-400 mb-1 flex items-center gap-1"><FaUser /> Full Name</label>
                        <input 
                            type="text" 
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500"
                            required
                        />
                    </div>
                    <div>
                        <label className="block text-sm text-gray-400 mb-1 flex items-center gap-1"><FaEnvelope /> Email</label>
                        <input 
                            type="email" 
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500"
                            required
                        />
                    </div>
                    <div>
                        <label className="block text-sm text-gray-400 mb-1 flex items-center gap-1"><FaLock /> Password</label>
                        <input 
                            type="password" 
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500"
                            required
                        />
                    </div>
                    {/* <div>
                        <label className="block text-sm text-gray-400 mb-1">Role</label>
                        <select 
                            value={role} 
                            onChange={(e) => setRole(e.target.value)}
                            className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500"
                        >
                            <option value="customer">Customer</option>
                            <option value="worker">Worker</option>
                        </select>
                    </div> */}
                    <button 
                        type="submit"
                        className="w-full bg-emerald-600 hover:bg-emerald-500 p-3 rounded-lg font-semibold transition mt-2"
                    >
                        Register
                    </button>
                </form>
            </div>
        </div>
    );
}
